"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.merging import intersect_spans, merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span


def check_inside(spans: List[Span], opening: Span) -> None:
    for span in spans:
        if intersect_spans(span, opening) != span:
            text = format_span(span)
            raise ValueError(f"outside opening hours: {text}")


def edge_pairs(spans: List[Span], opening: Span):
    points = [opening.start]
    for span in spans:
        points += [span.start, span.end]
    points.append(opening.end)
    return zip(points[::2], points[1::2])


def gap_spans(spans: List[Span], opening: Span) -> List[Span]:
    pairs = edge_pairs(spans, opening)
    return [
        Span(*pair)
        for pair in pairs
        if pair[0] < pair[1]
    ]


def gap_label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"


def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Label each uncovered stretch; raise if work is outside."""
    spans = merge_spans(worked)
    check_inside(spans, opening)
    return list(map(gap_label, gap_spans(spans, opening)))

