# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = find_gaps(
            spans("09:00-12:00", "13:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(["gap 12:00-13:00 (60 min)"], result)

    def test_gaps_at_both_ends(self):
        result = find_gaps(
            spans("10:00-11:00"), parse_span("09:00-12:00")
        )
        self.assertEqual(
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)"
            ],
            result,
        )

    def test_overlaps_leave_no_gap(self):
        result = find_gaps(
            spans("09:00-13:00", "12:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual([], result)

    def test_nobody_working_is_one_gap(self):
        result = find_gaps([], parse_span("09:00-10:30"))
        self.assertEqual(["gap 09:00-10:30 (90 min)"], result)

    def test_span_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(
                spans("08:00-10:00"), parse_span("09:00-17:00")
            )
